<template><div class="app-container"><el-form inline><el-form-item label="历史序列"><el-select v-model="thscode" filterable style="width:300px" @change="load"><el-option v-for="item in series" :key="item.thscode" :value="item.thscode" :label="`${item.thscode}｜${item.series_name||item.product_code}（${item.samples}）`" /></el-select></el-form-item></el-form><el-table v-loading="loading" :data="rows" border height="650"><el-table-column prop="trade_date" label="交易日" /><el-table-column prop="open_price" label="开盘" /><el-table-column prop="high_price" label="最高" /><el-table-column prop="low_price" label="最低" /><el-table-column prop="close_price" label="收盘" /><el-table-column prop="volume" label="成交量" /><el-table-column prop="turnover" label="成交额" /></el-table></div></template>
<script setup name="FutureHistoryDaily">
import { ref } from 'vue'; import { listFutureHistoryDaily,listFutureHistorySeries } from '@/api/future/history'
const series=ref([]),thscode=ref(''),rows=ref([]),loading=ref(false);function load(){if(!thscode.value)return;loading.value=true;listFutureHistoryDaily(thscode.value).then(r=>rows.value=r.data||[]).finally(()=>loading.value=false)}listFutureHistorySeries().then(r=>{series.value=r.data||[];thscode.value=series.value[0]?.thscode||'';load()})
</script>
